# Obtain an access token using an API Client
Obtain an access token using the OAuth2 client credentials flow
<Recipe slug="client-credentials-authorization" title="Client Credentials Authorization" backgroundColor="#444444" link="https://developer.jamf.com/v11.14.0/recipes/client-credentials-authorization" emoji="" />
# OpenAPI definition
```json
{
  "openapi": "3.0.1",
  "info": {
    "title": "Jamf Pro API",
    "termsOfService": "https://www.jamf.com/developer-resources/api-license-agreement",
    "version": "11.33.0"
  },
  "servers": [
    {
      "url": "https://yourServer.jamfcloud.com/api"
    }
  ],
  "x-readme": {
    "samples-languages": [
      "curl",
      "swift",
      "ruby",
      "python"
    ],
    "explorer-enabled": false
  },
  "security": [
    {
      "Bearer": []
    },
    {
      "ApiClient": []
    },
    {
      "BasicAuth": [
        "/v1/auth/token"
      ]
    }
  ],
  "paths": {
    "/v1/oauth/token": {
      "post": {
        "tags": [
          "api-authentication"
        ],
        "summary": "Obtain an access token using an API Client",
        "description": "Obtain an access token using the OAuth2 client credentials flow",
        "operationId": "postOAuthToken",
        "requestBody": {
          "description": "Client credential token request",
          "content": {
            "application/x-www-form-urlencoded": {
              "schema": {
                "$ref": "#/components/schemas/OAuthTokenRequest"
              }
            }
          },
          "required": true
        },
        "responses": {
          "200": {
            "description": "OAuth2 token obtained successfully",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/OAuthTokenResponse"
                }
              }
            }
          },
          "400": {
            "description": "Bad request. These differ from standard Jamf Pro API error response for better compatability\nwith a wide variety of standard clients. See https://datatracker.ietf.org/doc/html/rfc6749#section
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/OAuthTokenEndpointErrorResponse"
                }
              }
            }
          }
        },
        "x-action": true,
        "x-authentication-required": false
      }
    }
  },
  "components": {
    "schemas": {
      "OAuthTokenEndpointErrorResponse": {
        "required": [
          "error"
        ],
        "type": "object",
        "properties": {
          "error": {
            "type": "string",
            "example": "invalid_client"
          },
          "error_description": {
            "type": "string",
            "example": "OAuth 2.0 Parameter: grant_type"
          },
          "error_uri": {
            "type": "string",
            "example": "https://datatracker.ietf.org/doc/html/rfc6749#section-5.2"
          }
        }
      },
      "OAuthTokenRequest": {
        "required": [
          "client_id",
          "client_secret",
          "grant_type"
        ],
        "type": "object",
        "properties": {
          "grant_type": {
            "type": "string",
            "description": "OAuth2 grant type. For Jamf Pro API Clients, use `client_credentials`",
            "example": "client_credentials"
          },
          "client_id": {
            "type": "string",
            "description": "Client ID from your API Client",
            "example": "1979ca82-1337-c0de-1012-82a008a3bf70"
          },
          "client_secret": {
            "type": "string",
            "description": "Client secret from your API Client",
            "format": "password",
            "writeOnly": true,
            "example": "REDACTED"
          },
          "scope": {
            "type": "string",
            "description": "Optional. Provide a space-delimited list of roles that are within the configuration for \nthis API Client. Omitting this field will grant an access token that includes all of this client's \na
            "example": "api-role:1 api-role:2"
          }
        }
      },
      "OAuthTokenResponse": {
        "required": [
          "access_token",
          "expires_in",
          "scope",
          "token_type"
        ],
        "type": "object",
        "properties": {
          "access_token": {
            "type": "string",
            "example": "eyJhbGciOiJIUzI1NiJ9.REDACTED.REDACTED"
          },
          "token_type": {
            "type": "string",
            "example": "Bearer"
          },
          "scope": {
            "type": "string",
            "description": "Space-delimited list of API Roles, formatted and identified by ID like `api-role:{apiRoleId}`.",
            "example": "api-role:1 api-role:2"
          },
          "expires_in": {
            "type": "integer",
            "description": "Seconds until this access token is expired. This will reflect the `accessTokenLifetimeSeconds` value configured on your API Client.",
            "example": 60
          }
        }
      }
    },
    "securitySchemes": {
      "Bearer": {
        "type": "http",
        "scheme": "bearer",
        "bearerFormat": "JWT"
      },
      "BasicAuth": {
        "type": "http",
        "description": "Basic auth is used only for obtaining bearer tokens from the /v1/auth/token endpoint",
        "scheme": "basic"
      },
      "ApiClient": {
        "type": "oauth2",
        "description": "Jamf Pro API Roles and Clients provide a client ID and secret for obtaining access tokens using the OAuth2 client_credentials grant type",
        "flows": {
          "clientCredentials": {
            "tokenUrl": "/api/v1/oauth/token",
            "scopes": {}
          }
        }
      }
    }
  }
}

